// Edite aqui. É o único lugar com endereço da ponte, token, tamanho da edição e das imagens.
return [{ json: {
  // A ponte roda no computador, como o usuário cadu (scripts/ponte.py). De dentro do container
  // runv2-n8n-1 o computador é o gateway da rede runv2_default: 172.19.0.1.
  // (host.docker.internal NÃO existe nesse container; ele não tem extra_hosts.)
  url_ponte: 'http://172.19.0.1:7777',
  token_ponte: 'qFPgEFVBoIrIG2aHrN02aMR2YprNczxM',
  // A IA escolhe entre noticias_min e noticias_max notícias. Até 6 o carrossel leva o Índice
  // (o modelo de Índice do news tem 6 itens); com mais de 6, o Índice fica de fora.
  noticias_min: 4,
  noticias_max: 6,
  serie: 'news',
  assunto: 'IA em foco',        // entra no nome dos arquivos dos cards
  marca: '@iaclube',
  // Acrescentado ao fim de todo prompt de imagem: é o que deixa as imagens com a mesma cara.
  estilo_comum: "flat vector editorial illustration, bold simple shapes, soft gradients, blue and warm yellow palette, clean composition, wide landscape framing, no text, no letters, no numbers, no logos, no watermark",
  // Tamanho das imagens (múltiplos de 16). Pequena 3:2 = 624 x 416 (cerca de 4 min cada).
  // Média 3:2 = 944 x 624 (cerca de 9 min cada). O espaço da imagem no card é 839 x 592.
  largura: 624,
  altura: 416,
  espera_subir_s: 5,            // pausa depois de subir cada servidor
  intervalo_consulta_s: 30,     // de quanto em quanto tempo olhar a fila de imagens
  tempo_maximo_geracao_min: 240 // desiste se as imagens passarem disso
} }];

// Lista de feeds RSS. O node seguinte (RSS Feed Read) roda uma vez por item
// recebido, entao cada linha daqui vira uma leitura de feed.
// Para adicionar ou remover fonte, basta editar este array.
const feeds = [
  { fonte: 'OpenAI',          url: 'https://openai.com/news/rss.xml' },
  { fonte: 'Google DeepMind', url: 'https://deepmind.google/blog/rss.xml' },
  { fonte: 'TechCrunch',      url: 'https://techcrunch.com/category/artificial-intelligence/feed/' },
  { fonte: 'The Verge',       url: 'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml' },
  { fonte: 'Anthropic',       url: 'https://raw.githubusercontent.com/taobojlen/anthropic-rss-feed/main/anthropic_news_rss.xml' }
];

return feeds.map(f => ({ json: f }));

// Recebe TODAS as noticias de TODOS os feeds e faz tres coisas:
// 1. descarta o que e mais velho que 7 dias
// 2. descarta o que ja virou post (cruzamento com a Data Table)
// 3. monta o texto que vai no prompt da IA

function normalizar(texto) {
  return String(texto || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w\s]/g, "")
    .replace(/\s+/g, " ");
}

// --- memoria: o que ja foi publicado ---
const memoria = $('Memoria - ler').all().map(i => i.json);
const titulosUsados = new Set(
  memoria.map(l => l.titulo_normalizado || normalizar(l.titulo)).filter(t => t)
);
const linksUsados = new Set(
  memoria.map(l => l.link).filter(l => l)
);

// --- janela de 7 dias ---
const AGORA = Date.now();
const LIMITE = AGORA - 7 * 24 * 60 * 60 * 1000;

const brutas = $input.all().map(i => i.json);

let semData = 0;
let velhas = 0;
let repetidas = 0;

const vistas = new Set(); // evita a mesma noticia vinda de dois feeds
const selecionadas = [];

for (const item of brutas) {
  // O RSS Feed Read as vezes devolve um item vazio (feed fora do ar +
  // Always Output Data). Esse guard evita quebrar o loop.
  if (!item || !item.title) continue;

  // Cada feed nomeia o campo de data de um jeito. Tentamos todos.
  const dataBruta = item.isoDate || item.pubDate || item.date || item.published;
  const ts = dataBruta ? Date.parse(dataBruta) : NaN;

  if (isNaN(ts)) { semData++; continue; }
  if (ts < LIMITE) { velhas++; continue; }

  const norm = normalizar(item.title);
  const link = item.link || '';

  if (titulosUsados.has(norm) || (link && linksUsados.has(link))) { repetidas++; continue; }
  if (vistas.has(norm)) { repetidas++; continue; }
  vistas.add(norm);

  // A fonte vem do dominio do link: o RSS Feed Read substitui o $json e
  // perde o campo "fonte" que veio do node Lista de feeds.
  let fonte = 'desconhecida';
  try {
    fonte = new URL(link).hostname.replace(/^www\./, '');
  } catch (e) { /* link ausente ou malformado: mantem 'desconhecida' */ }

  const resumo = String(item.contentSnippet || item.content || item.description || '')
    .replace(/<[^>]*>/g, ' ')   // tira tags HTML
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 400);

  selecionadas.push({
    manchete: item.title.trim(),
    resumo,
    fonte,
    link,
    data: new Date(ts).toISOString(),
    data_br: new Date(ts).toLocaleDateString('pt-BR'),
    titulo_normalizado: norm,
    ts
  });
}

// Mais recentes primeiro, no maximo 30 (o prompt fica grande demais alem disso)
selecionadas.sort((a, b) => b.ts - a.ts);
const top = selecionadas.slice(0, 30);

// Texto numerado que vai direto no prompt
const noticias_disponiveis = top
  .map((n, i) => `${i + 1}. [${n.fonte} | ${n.data_br}] ${n.manchete}\n   Link: ${n.link}\n   Resumo: ${n.resumo}`)
  .join('\n\n');

return [{
  json: {
    total_disponiveis: top.length,
    noticias_disponiveis,
    noticias_lista: top,
    data_hoje: new Date().toLocaleDateString('pt-BR'),
    // contadores para depuracao: aparecem na saida do node
    descartadas_sem_data: semData,
    descartadas_por_idade: velhas,
    descartadas_repetidas: repetidas,
    total_lido: brutas.length
  }
}];

try {
  const raw = $input.first().json.output;

  let clean = String(raw).replace(/```json|```/g, '').trim();

  const inicio = clean.indexOf('{');
  const fim = clean.lastIndexOf('}');
  if (inicio !== -1 && fim !== -1) {
    clean = clean.slice(inicio, fim + 1);
  }

  const parsed = JSON.parse(clean);

  // ---------- 1) CONTRATO MINIMO ----------
  const faltando = [];
  if (!parsed.titulo_edicao) faltando.push('titulo_edicao');
  if (!parsed.tema_card) faltando.push('tema_card');
  if (!Array.isArray(parsed.noticias) || parsed.noticias.length === 0) faltando.push('noticias');
  if (!parsed.gancho || !parsed.gancho.texto) faltando.push('gancho.texto');
  if (!parsed.legendas) faltando.push('legendas');
  else {
    for (const rede of ['instagram', 'facebook', 'linkedin']) {
      if (!parsed.legendas[rede]) faltando.push('legendas.' + rede);
    }
  }

  if (faltando.length) {
    return [{ json: { erro: true, mensagem: 'Campos ausentes: ' + faltando.join(', '), bruto: clean } }];
  }

  const avisos = [];

  // O modelo foi instruido a nao escrever slides -- a automacao monta.
  if (Array.isArray(parsed.slides) && parsed.slides.length) {
    avisos.push('a IA devolveu um array "slides" (' + parsed.slides.length + ' itens); foi ignorado, os slides sao montados pela automacao');
  }
  delete parsed.slides;

  // ---------- 2) CAMPOS POR NOTICIA ----------
  parsed.noticias.forEach((n, i) => {
    if (!n.manchete) avisos.push('noticia ' + (i + 1) + ' sem manchete');
    if (!n.texto_slide) avisos.push('noticia ' + (i + 1) + ' sem texto_slide -- o slide dela vai sair vazio');
    if (!n.rotulo_indice) avisos.push('noticia ' + (i + 1) + ' sem rotulo_indice -- vai faltar no slide de indice');
    if (!n.prompt_imagem) avisos.push('noticia ' + (i + 1) + ' sem prompt_imagem -- a imagem vai sair de um prompt generico');
  });

  // ---------- 3) A CAPA PRECISA APONTAR PARA UMA NOTICIA SELECIONADA ----------
  // Sem isso a capa promete um assunto que o carrossel nao entrega.
  const indices = parsed.noticias.map(n => Number(n.indice)).filter(Number.isInteger);
  let alvo = Number(parsed.gancho.indice_noticia);
  if (!indices.includes(alvo)) {
    alvo = indices.length ? indices[0] : null;
    parsed.gancho.indice_noticia = alvo;
    parsed.capa_suspeita = true;
    avisos.push('a capa nao aponta para nenhuma noticia selecionada -- conferir se ela fala da primeira noticia do carrossel');
  } else {
    parsed.capa_suspeita = false;
  }

  if (!parsed.gancho.titulo) {
    parsed.gancho.titulo = String(parsed.titulo_edicao || 'Esta semana');
    avisos.push('gancho sem titulo -- usado o titulo da edicao');
  }

  // ---------- 4) LIMITES E REFERENCIAS QUEBRADAS (avisos, nao bloqueiam) ----------
  const lim = (valor, max, rotulo) => {
    const n = String(valor || '').length;
    if (n > max) avisos.push(rotulo + ' com ' + n + ' chars, limite ' + max);
  };

  // Limites dos modelos do conjunto news (iaclube_n8n/templates/news/limites.json).
  lim(parsed.gancho.titulo, 20, 'titulo da capa');
  lim(parsed.gancho.texto, 95, 'texto da capa');

  parsed.noticias.forEach((n, i) => {
    lim(n.manchete, 31, 'manchete da noticia ' + (i + 1) + ' (vira titulo de slide)');
    lim(n.rotulo_indice, 20, 'rotulo_indice da noticia ' + (i + 1));
    lim(n.prompt_imagem, 300, 'prompt_imagem da noticia ' + (i + 1));
    lim(n.resumo, 300, 'resumo da noticia ' + (i + 1));
    lim(n.por_que_importa, 150, 'por_que_importa da noticia ' + (i + 1));
    const t = String(n.texto_slide || '').length;
    if (t > 167) avisos.push('texto_slide da noticia ' + (i + 1) + ' com ' + t + ' chars, limite 167');
    if (t && t < 90) avisos.push('texto_slide da noticia ' + (i + 1) + ' com ' + t + ' chars, minimo 90');
  });

  // As fontes so existem na legenda. Se o modelo apontar para outro lugar,
  // ou enfiar URL na arte, o aviso aparece no card.
  const proibido = /pr[oó]ximo slide|slide seguinte|slide a seguir|logo abaixo|aqui embaixo|nos coment[aá]rios|link da bio/i;
  const anunciaEdicao = /confira|resumo (da |desta )?semana|principais not[ií]cias|not[ií]cias da semana/i;

  const textosSlide = [
    { rotulo: 'capa', texto: parsed.gancho.titulo + ' ' + parsed.gancho.texto }
  ].concat(parsed.noticias.map((n, i) => ({
    rotulo: 'noticia ' + (i + 1),
    texto: (n.manchete || '') + ' ' + (n.texto_slide || '')
  })));

  textosSlide.forEach(s => {
    if (proibido.test(s.texto)) avisos.push(s.rotulo + ' aponta para lugar inexistente');
    if (/https?:\/\//i.test(s.texto)) avisos.push(s.rotulo + ' tem URL no texto');
  });

  // A chamada "confira essa e mais noticias da semana" e fixa e adicionada por
  // codigo. Se o modelo escrever algo parecido na capa, sai duplicado.
  if (anunciaEdicao.test(parsed.gancho.titulo + ' ' + parsed.gancho.texto)) {
    avisos.push('a capa anuncia a edicao em vez de dar o fato -- a chamada fixa ja faz isso, vai sair repetido');
  }

  for (const rede of ['instagram', 'facebook', 'linkedin']) {
    if (proibido.test(parsed.legendas[rede])) avisos.push('legenda ' + rede + ' aponta para lugar inexistente');
  }

  return [{ json: { ...parsed, erro: false, avisos } }];
} catch (e) {
  return [{ json: { erro: true, mensagem: e.message } }];
}

// Prepara os dados para o Trello e para a memoria.
// Diferenca importante em relacao a segunda e quarta: aqui UM post cobre
// VARIAS noticias, entao a normalizacao acontece dentro de cada noticia.
function normalizar(texto) {
  return String(texto || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w\s]/g, "")
    .replace(/\s+/g, " ");
}

// Chave de comparacao de URL: ignora protocolo, www, parametros de rastreio
// (?utm_source=rss...) e barra final. Sem isso, o link do feed e o link copiado
// pelo modelo quase nunca batem por igualdade exata.
function chaveLink(url) {
  const bruto = String(url || '').trim();
  if (!bruto) return '';
  try {
    const u = new URL(bruto);
    return u.hostname.toLowerCase().replace(/^www\./, '') +
           u.pathname.toLowerCase().replace(/\/+$/, '');
  } catch (e) {
    return bruto.toLowerCase()
      .replace(/^https?:\/\//, '')
      .replace(/^www\./, '')
      .split(/[?#]/)[0]
      .replace(/\/+$/, '');
  }
}

function lista(valor) {
  return Array.isArray(valor) ? valor : [];
}

const dados = $input.first().json;

// A lista original (antes da IA escolher) serve para recuperar o link real e o
// titulo_normalizado da noticia do feed: a IA reescreve a manchete, e se
// gravassemos a versao reescrita a checagem de duplicata da proxima semana
// nunca daria match.
const original = $('Filtra e cruza memoria').first().json.noticias_lista || [];

const porLink = {};
original.forEach(n => {
  const k = chaveLink(n.link);
  if (k) porLink[k] = n;
});

let noticias = lista(dados.noticias).map(n => {
  // 1a tentativa: o numero da noticia na lista numerada do prompt.
  // Copiar um numero de um digito e muito mais confiavel que copiar uma URL.
  let base = null;
  let casou_por = 'nenhum';

  const idx = Number(n.indice);
  if (Number.isInteger(idx) && idx >= 1 && idx <= original.length) {
    base = original[idx - 1];
    casou_por = 'indice';
  }

  // 2a tentativa: link normalizado, caso o indice venha errado ou ausente.
  if (!base) {
    const achado = porLink[chaveLink(n.link)];
    if (achado) {
      base = achado;
      casou_por = 'link';
    }
  }

  return {
    indice: Number(n.indice),
    manchete: String(n.manchete || ''),
    rotulo_indice: String(n.rotulo_indice || n.manchete || ''),
    texto_slide: String(n.texto_slide || ''),
    resumo: String(n.resumo || ''),
    por_que_importa: String(n.por_que_importa || ''),
    prompt_imagem: String(n.prompt_imagem || '').replace(/\s+/g, ' ').trim(),
    fonte: base ? base.fonte : String(n.fonte || ''),
    // o link do feed manda: se o modelo mexeu na URL, a versao dele e descartada
    link: base ? base.link : String(n.link || ''),
    link_original_do_modelo: String(n.link || ''),
    titulo_memoria: base ? base.manchete : String(n.manchete || ''),
    titulo_normalizado: base ? base.titulo_normalizado : normalizar(n.manchete),
    link_confirmado: Boolean(base),
    casou_por
  };
});

const avisos = lista(dados.avisos).slice();

// A noticia da capa vai para a frente da fila. O gancho afirma o fato dela;
// se ela aparecesse no meio do carrossel, a promessa da capa ficaria pendurada.
const alvo = Number(dados.gancho && dados.gancho.indice_noticia);
const pos = noticias.findIndex(n => n.indice === alvo);
if (pos > 0) {
  const [capa] = noticias.splice(pos, 1);
  noticias.unshift(capa);
}

// Noticia que nao casou com nenhuma da lista pode ter sido inventada:
// esse e o pior erro possivel neste post, entao vira aviso no card.
noticias.forEach((n, i) => {
  if (!n.link_confirmado) {
    avisos.push(`noticia ${i + 1} nao casou com nenhuma da lista de feeds -- conferir antes de publicar`);
  }
});

// Se a noticia da capa e justamente uma nao confirmada, o erro sai na primeira
// tela do post. Isso nao bloqueia a execucao -- jogar fora a edicao inteira por
// causa de um item seria pior -- mas marca o card de forma dificil de ignorar.
const capaSuspeita = Boolean(dados.capa_suspeita) || (noticias.length > 0 && !noticias[0].link_confirmado);
if (capaSuspeita) {
  avisos.unshift('A CAPA PRECISA DE CONFERENCIA: a noticia da capa nao foi confirmada nos feeds ou nao foi identificada. Verificar antes de aprovar.');
}

return [{
  json: {
    ...dados,
    noticias,
    avisos,
    hashtags: lista(dados.hashtags),
    total_noticias: noticias.length,
    links_nao_confirmados: noticias.filter(n => !n.link_confirmado).length,
    capa_suspeita: capaSuspeita,
    prefixo_titulo: capaSuspeita ? '[CONFERIR CAPA] ' : '',
    data: new Date().toISOString(),
    status: "gerado"
  }
}];

// MONTAGEM DO CARROSSEL
// Os slides nao vem da IA: sao montados aqui a partir das noticias ja
// confirmadas contra os feeds. O motivo e sincronia -- quando o modelo escrevia
// a lista de slides por conta propria, nada garantia que ela correspondesse as
// noticias selecionadas, nem que o indice batesse com o que vinha depois.
//
// PAPEIS: gancho, contexto, desenvolvimento, cta. Sao os mesmos quatro usados
// em segunda e quarta, para o template de arte ter um vocabulario so.
//
// TEXTOS FIXOS: a chamada da capa e o slide de CTA vivem aqui e em nenhum outro
// lugar. Mudou aqui, mudou em toda edicao de sexta.

const CHAMADA_CAPA = 'Confira essa e mais notícias da semana:';
const PERFIL = '@iaclube';
const SITE = 'iaclube.help';

const d = $input.first().json;
const noticias = Array.isArray(d.noticias) ? d.noticias : [];
const g = d.gancho || {};

// O texto de slide precisa caber em uma linha: a descricao do card usa
// '### N | PAPEL | titulo' + uma linha de texto, e uma quebra aqui partiria
// o slide em dois na hora do parse.
const umaLinha = (t) => String(t || '').replace(/\s+/g, ' ').trim();

const slides = [];

// 1. capa: fato da semana + chamada fixa
slides.push({
  papel: 'gancho',
  titulo: umaLinha(g.titulo),
  texto: `${umaLinha(g.texto)} ${CHAMADA_CAPA}`.trim()
});

// 2. indice: as etiquetas das noticias que realmente entraram, na ordem em que
// aparecem. Montado a partir da lista final, entao nao tem como dessincronizar.
// Nao anuncia quantidade de proposito: o slide nao promete um numero.
const rotulos = noticias.map(n => umaLinha(n.rotulo_indice)).filter(r => r);
slides.push({
  papel: 'contexto',
  // 'Índice' e nao 'Nessa edição': o titulo do modelo de indice tem espaco para 6 letras.
  titulo: 'Índice',
  texto: rotulos.join(' · ')
});

// 3. uma noticia por slide
noticias.forEach(n => {
  slides.push({
    papel: 'desenvolvimento',
    titulo: umaLinha(n.manchete),
    texto: umaLinha(n.texto_slide)
  });
});

// 4. fechamento fixo
slides.push({
  papel: 'cta',
  titulo: 'Toda semana tem',
  texto: `As fontes estão na legenda. Segue o ${PERFIL} pra não perder o resumo da próxima semana. Mais em ${SITE}.`
});

// O indice cresce com o numero de noticias e pode estourar a arte.
const avisos = Array.isArray(d.avisos) ? d.avisos.slice() : [];
const tamIndice = slides[1].texto.length;
if (tamIndice > 160) {
  avisos.push(`slide de indice com ${tamIndice} chars -- encurtar os rotulos das noticias antes de gerar a arte`);
}

return [{ json: { ...d, slides, avisos } }];

// CONTRATO COM O FLUXO DE DESIGN
// A descricao do card pai e a fonte unica de verdade. O fluxo de design le esta
// descricao e corta pelos cabecalhos '## ' abaixo -- os mesmos usados nos fluxos
// de segunda e quarta, para um parser so atender os tres. Se voce editar o texto
// no Trello durante a revisao, edite DENTRO das secoes: nao apague nem renomeie
// os cabecalhos, senao o parser do design nao encontra nada.
//
// Cada slide vem marcado com o papel narrativo (GANCHO / CONTEXTO /
// DESENVOLVIMENTO / CTA). O papel escolhe o layout na hora da arte, entao nao
// remova o slide de CTA nem troque a ordem dos papeis na revisao.
//
// SOBRE AS FONTES: os links existem em UM lugar so, a secao '## FONTES'.
// A publicacao anexa esse bloco no fim de cada legenda. Por isso as legendas
// aqui terminam com um marcador -- e lembrete de que o texto publicado vai ser
// maior que o que voce ve, e de que corrigir um link e corrigir um lugar so.

const d = $input.first().json;

const MARCADOR = '>> Na publicacao, o bloco FONTES entra aqui.';

const noticias = d.noticias
  .map((n, i) => {
    const alerta = n.link_confirmado ? '' : '  [LINK NAO CONFIRMADO]';
    return `### ${i + 1} | ${n.manchete}${alerta}\nFonte: ${n.fonte}\nPor que importa: ${n.por_que_importa}\n${n.resumo}`;
  })
  .join('\n\n');

const slides = d.slides
  .map((s, i) => `### ${i + 1} | ${String(s.papel || '').toUpperCase()} | ${s.titulo}\n${s.texto}`)
  .join('\n\n');

// Linha comecando com '#' vira titulo no markdown do Trello e a primeira
// hashtag some da tela. A barra invertida escapa; o parser do design remove.
const hashtags = d.hashtags.join(' ').replace(/^#/, '\\#');

// Os prompts de imagem ficam no card para conferencia: e deles que a arte sai.
const prompts = d.noticias
  .map((n, i) => `${i + 1}. ${n.prompt_imagem || '(sem prompt: a automacao usa um generico)'}`)
  .join('\n');

const fontes = d.noticias
  .map(n => `${n.fonte}: ${n.link}`)
  .join('\n');

const partes = [];

// O alerta de capa vem antes de tudo: e o unico erro deste post que aparece na
// primeira tela para quem esta rolando o feed.
if (d.capa_suspeita) {
  partes.push('**[CONFERIR CAPA] A noticia da capa nao foi confirmada nos feeds. Validar antes de aprovar.**', '');
}

partes.push(
  d.titulo_edicao,
  '',
  `${d.total_noticias} noticias nesta edicao.`,
  '',
  '## NOTICIAS',
  noticias,
  '',
  '## SLIDES',
  slides,
  '',
  '## LEGENDA INSTAGRAM',
  d.legendas.instagram,
  MARCADOR,
  '',
  '## LEGENDA FACEBOOK',
  d.legendas.facebook,
  MARCADOR,
  '',
  '## LEGENDA LINKEDIN',
  d.legendas.linkedin,
  MARCADOR,
  '',
  '## HASHTAGS',
  hashtags,
  '',
  '## PROMPTS DE IMAGEM',
  prompts,
  '',
  '## FONTES',
  fontes
);

if (d.avisos && d.avisos.length) {
  partes.push('', '## AVISOS DA AUTOMACAO', d.avisos.map(a => `- ${a}`).join('\n'));
}

return [{
  json: {
    ...d,
    descricao: partes.join('\n')
  }
}];

// Depois do node de checklist, $json e o objeto da checklist -- entao $json.id
// e o checklistId. Um item entra e um item sai: sem risco de pareamento.
const checklistId = $input.first().json.id;

// Noticia envelhece rapido e link errado destroi a credibilidade da pagina:
// por isso a conferencia das fontes vem antes da arte.
const tarefas = [
  'Conferir se as noticias ainda estao atuais',
  'Abrir e validar cada link da secao FONTES',
  'Ler so o slide 1: o fato da capa esta correto e e o mais forte da semana?',
  'Conferir se a capa fala da primeira noticia do carrossel',
  'Revisar o slide de indice: os rotulos dizem o assunto sem spoiler?',
  'Revisar as tres legendas',
  'Aprovar texto (mover card para Aprovado)',
  'Conferir os cards gerados (a pasta vem num comentario deste card)',
  'Aprovar arte',
  'Publicar nas tres redes'
];

return [{ json: { checklistId, tarefas } }];

// Transforma a lista de noticias do post em UMA LINHA POR NOTICIA.
// O node Data Table seguinte roda uma vez por item recebido, entao esse Code
// e o que faz a memoria de sexta gravar 4-6 registros em vez de 1.
const dados = $('Normaliza noticias').first().json;
const noticias = Array.isArray(dados.noticias) ? dados.noticias : [];

return noticias.map(n => ({
  json: {
    titulo: n.titulo_memoria,
    titulo_normalizado: n.titulo_normalizado,
    link: n.link,
    fonte: n.fonte,
    data: dados.data,
    status: dados.status
  }
}));

// PONTE ENTRE O TEXTO E A ARTE
// Transforma a edicao que acabou de ir para o Trello no mesmo formato do arquivo
// entradas/exemplo-noticias-10.json, que o resto do fluxo (igual ao noticias-2-arte) espera:
//   { nome, estilo_comum, entrada: { serie, data, assunto, marca, cards }, imagens }
// Os textos vem dos slides de 'Monta slides do carrossel': o que esta no card do Trello e o
// que vai para a arte. Ordem dos cards: capa, indice, uma noticia por card, encerramento.
const cfg = $('Configuração').first().json;
const d = $('Monta slides do carrossel').first().json;
const noticias = Array.isArray(d.noticias) ? d.noticias : [];
const slides = Array.isArray(d.slides) ? d.slides : [];
const doPapel = (papel) => slides.filter(s => s.papel === papel);
const umaLinha = (t) => String(t || '').replace(/\s+/g, ' ').trim();

// nome de arquivo seguro para o gerador: minusculas, sem acento, so letras, numeros e '-'
const slug = (t) => String(t || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
  .slice(0, 40).replace(/-+$/g, '');

const capa = doPapel('gancho')[0] || { titulo: '', texto: '' };
const indice = doPapel('contexto')[0] || { titulo: 'Índice' };
const corpo = doPapel('desenvolvimento');
const fim = doPapel('cta')[0] || { titulo: '', texto: '' };

const cards = [];
const imagens = [];

cards.push({ modelo: 'capa', campos: { titulo: capa.titulo, corpo: capa.texto } });

// O modelo de indice do news tem 6 itens (item_1 a item_6). Com mais noticias, fica de fora.
if (noticias.length <= 6) {
  const campos = { titulo: indice.titulo };
  noticias.forEach((n, i) => { campos['item_' + (i + 1)] = umaLinha(n.rotulo_indice || n.manchete); });
  cards.push({ modelo: 'indice', campos });
}

noticias.forEach((n, i) => {
  const s = corpo[i] || { titulo: umaLinha(n.manchete), texto: umaLinha(n.texto_slide) };
  cards.push({ modelo: 'texto-com-imagem', campos: { titulo: s.titulo, corpo: s.texto } });
  const prompt = umaLinha(n.prompt_imagem) ||
    'an editorial illustration about artificial intelligence news, ' + umaLinha(n.rotulo_indice || n.manchete);
  imagens.push({
    card: cards.length,            // posicao do card que acabou de entrar (o primeiro e 1)
    mascara: 'imagem_1',
    nome_arquivo: 'noticia-' + String(i + 1).padStart(2, '0') + (slug(n.rotulo_indice) ? '-' + slug(n.rotulo_indice) : ''),
    prompt,
  });
});

cards.push({ modelo: 'encerramento', campos: { titulo: fim.titulo, corpo: fim.texto } });

const data = $now.toISODate();
return [{ json: {
  versao: 1,
  nome: ('Notícias IA ' + data + ' ' + umaLinha(d.tema_card)).trim().slice(0, 80),
  estilo_comum: cfg.estilo_comum || '',
  entrada: { serie: cfg.serie, data, assunto: cfg.assunto, marca: cfg.marca, cards },
  imagens,
} }];

const cfg = $('Configuração').first().json;
const dados = $input.first().json;

const erros = [];
const cards = dados.entrada && dados.entrada.cards;
if (!Array.isArray(cards) || cards.length === 0) erros.push('entrada.cards precisa ser uma lista com pelo menos um card');
if (!Array.isArray(dados.imagens) || dados.imagens.length === 0) erros.push('imagens precisa ser uma lista com pelo menos uma imagem');
if (dados.imagens && dados.imagens.length > 20) erros.push('no máximo 20 imagens por execução (limite da consulta de fila)');
if (cfg.largura % 16 || cfg.altura % 16) erros.push('largura e altura da Configuração precisam ser múltiplos de 16');

const usados = new Set();
(dados.imagens || []).forEach((im, i) => {
  const onde = 'imagens[' + i + ']';
  if (!Number.isInteger(im.card) || !cards || im.card < 1 || im.card > cards.length) {
    erros.push(onde + '.card deve ser a posição de um card (1 a ' + (cards ? cards.length : '?') + ')');
  } else if (usados.has(im.card + '/' + im.mascara)) {
    erros.push(onde + ': o card ' + im.card + ' já tem imagem para a máscara ' + im.mascara);
  } else {
    usados.add(im.card + '/' + im.mascara);
  }
  if (typeof im.mascara !== 'string' || !im.mascara) erros.push(onde + '.mascara é obrigatória (por exemplo imagem_1)');
  if (typeof im.prompt !== 'string' || im.prompt.trim().length < 3) erros.push(onde + '.prompt é obrigatório');
});
if (erros.length) throw new Error('Entrada inválida:\n- ' + erros.join('\n- '));

return [{ json: {
  cfg,
  nome: dados.nome || 'carrossel_noticias',
  estilo_comum: (dados.estilo_comum || '').trim(),
  entrada: dados.entrada,
  imagens: dados.imagens,
} }];

const v = $('Validar entrada').first().json;
const { largura, altura } = v.cfg;
return v.imagens.map((im, i) => {
  const nome = im.nome_arquivo || 'noticia-' + String(i + 1).padStart(2, '0');
  const prompt = v.estilo_comum ? im.prompt.trim() + ', ' + v.estilo_comum : im.prompt.trim();
  return { json: {
    indice: i,
    card: im.card,
    mascara: im.mascara,
    nome_arquivo: nome,
    corpo: { prompt, width: largura, height: altura, nome_arquivo: nome },
  } };
});

const pedidos = $('Montar pedidos de imagem').all();
const respostas = $input.all();
const tickets = respostas.map((r, i) => ({
  ticket: r.json.ticket,
  card: pedidos[i].json.card,
  mascara: pedidos[i].json.mascara,
  nome_arquivo: pedidos[i].json.nome_arquivo,
}));
return [{ json: { tickets, total: tickets.length, iniciado_em: Date.now() } }];

const r = $('Reunir tickets').first().json;
const cfg = $('Validar entrada').first().json.cfg;
const jobs = $input.first().json.jobs || {};
const cont = { queued: 0, running: 0, completed: 0, failed: 0, outro: 0 };
const falhas = [];
for (const t of r.tickets) {
  const j = jobs[t.ticket] || { status: 'not_found' };
  if (j.status in cont) cont[j.status]++; else cont.outro++;
  if (j.status === 'failed' || j.status === 'not_found') {
    falhas.push('card ' + t.card + ' (' + t.nome_arquivo + '): ' + (j.error || j.status));
  }
}
const minutos = Math.round((Date.now() - r.iniciado_em) / 6000) / 10;
let estado = 'esperando';
let motivo = '';
if (falhas.length) {
  estado = 'falhou';
  motivo = 'Falha ao gerar imagem: ' + falhas.join(' | ');
} else if (cont.completed === r.total) {
  estado = 'concluido';
} else if (minutos > cfg.tempo_maximo_geracao_min) {
  estado = 'tempo_esgotado';
  motivo = 'As imagens passaram de ' + cfg.tempo_maximo_geracao_min + ' min e ainda faltam ' + (r.total - cont.completed) + '.';
}
return [{ json: { estado, motivo, minutos, total: r.total, ...cont } }];

const v = $('Validar entrada').first().json;
const tickets = $('Listar tickets').all();
const resultados = $input.all();
const imagens = [];
const problemas = [];
resultados.forEach((r, i) => {
  const t = tickets[i].json;
  const caminho = r.json.output_path;
  if (!r.json.ready || !caminho) {
    problemas.push('card ' + t.card + ' (' + t.nome_arquivo + '): imagem sem caminho de arquivo');
  } else {
    imagens.push({ card: t.card, mascara: t.mascara, caminho });
  }
});
if (problemas.length) return [{ json: { ok: false, motivo: problemas.join(' | ') } }];
return [{ json: { ok: true, pedido: {
  versao: 1,
  nome: v.nome,
  entrada: v.entrada,
  imagens,
  exportacao: { formatos: ['png'], escalas: [1] },
} } }];

const r = $input.first().json;
const arquivos = (r.arquivos || []);
return [{ json: {
  ok: r.ok === true,
  pasta: r.pasta,
  geracao_id: r.geracao_id,
  quantidade: arquivos.length,
  arquivos: arquivos.map(a => a.caminho),
  avisos: (r.avisos || []).map(a => (a.rotulo ? a.rotulo + ': ' : '') + a.mensagem),
} }];

// Devolve o resultado da produção (os nós anteriores só desligaram o servidor e comentaram no Trello).
const t = $('Trello - Criar card').first().json;
return [{ json: { ...$('Montar resultado').first().json, trello: t.shortUrl || t.url || t.id } }];

const j = $input.first().json;
let msg;
if (j.motivo) {
  msg = j.motivo;
} else if (j.ready === false) {
  msg = 'O gerador subiu, mas não está pronto: ' + (j.problems || []).join(' | ');
} else if (j.error) {
  const e = j.error;
  msg = (e.message || JSON.stringify(e)) + (e.description ? ' — ' + e.description : '');
} else if (j.stdout) {
  msg = j.stdout;
} else {
  msg = 'Falha sem detalhe: ' + JSON.stringify(j).slice(0, 500);
}
return [{ json: { mensagem: msg } }];

